 "content": "def transform(grid):
    # The only demonstrated alteration recolors the largest non-background
    # object to color 1. Use 8-connected components so same-color diagonals
    # belong to the same object (as in the lower-left demo shape).
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if (dy or dx) and 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            objects.append((len(cells), cells))
    if objects:
        _, cells = max(objects, key=lambda item: item[0])
        for r, c in cells:
            out[r][c] = 1
    return out
"
}

