def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        yy,xx=y+dy,x+dx
                        if (dy or dx) and 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
            objects.append((len(cells), color, cells))
    out=[row[:] for row in grid]
    # Demo: the largest 8-connected object is recolored to the color of the
    # smallest non-background component (1 in demo; 8 in this test).
    if objects:
        _, _, cells=max(objects, key=lambda x:x[0])
        _, replacement, _=min(objects, key=lambda x:x[0])
        for r,c in cells: out[r][c]=replacement
    return out

