def transform(grid):
    # Recolor the largest 4-connected component of color 6 to color 1.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    largest = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 6 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(cells) > len(largest):
                largest = cells
    for r, c in largest:
        out[r][c] = 8
    return out

